    Bug 1990571 - Continue traversal of a parent folder when a sub-hierarchy fails. r=tobyp

    Differential Revision: https://phabricator.services.mozilla.com/D273604

diff --git a/mailnews/base/src/nsMsgDBFolder.cpp b/mailnews/base/src/nsMsgDBFolder.cpp
index 73191a11841..ab9118726a8 100644
--- a/mailnews/base/src/nsMsgDBFolder.cpp
+++ b/mailnews/base/src/nsMsgDBFolder.cpp
@@ -3424,6 +3424,16 @@ NS_IMETHODIMP nsMsgDBFolder::AddSubfolder(const nsACString& name,
       return rv;
     }

+    // `CreateFolderAndCache` will return `NS_MSG_FOLDER_EXISTS` in two cases:
+    // 1. This folder object already has a child with the specified name.
+    // 2. This folder object already has a child with the specified URI.
+    // In both cases, that means `mSubFolders` already contains a child with the
+    // given name. This cannot be treated as an error condition because the
+    // folder lookup service reuses folder objects for the same URI, so a folder
+    // that already exists in the cache with this folder's URI will also already
+    // have children matching the child folder's URI. This can be changed once
+    // dangling folders are removed. See
+    // https://bugzilla.mozilla.org/show_bug.cgi?id=1679333
     if (NS_SUCCEEDED(rv)) {
       mSubFolders.AppendObject(folder);
     }
diff --git a/mailnews/protocols/common/src/FolderPopulation.cpp b/mailnews/protocols/common/src/FolderPopulation.cpp
index 9b041417ece..e03009b13fa 100644
--- a/mailnews/protocols/common/src/FolderPopulation.cpp
+++ b/mailnews/protocols/common/src/FolderPopulation.cpp
@@ -8,6 +8,7 @@
 #include "nsCOMPtr.h"
 #include "nsIMsgFolder.h"
 #include "nsIMsgPluggableStore.h"
+#include "nsPrintfCString.h"

 nsresult PopulateFolderHierarchy(nsIMsgFolder* parent,
                                  nsIMsgPluggableStore* messageStore,
@@ -16,6 +17,10 @@ nsresult PopulateFolderHierarchy(nsIMsgFolder* parent,
   nsresult rv = messageStore->DiscoverChildFolders(parent, childFolderNames);
   NS_ENSURE_SUCCESS(rv, rv);

+  nsAutoCString parentName;
+  rv = parent->GetName(parentName);
+  NS_ENSURE_SUCCESS(rv, rv);
+
   for (auto&& childFolderName : childFolderNames) {
     nsCOMPtr<nsIMsgFolder> childFolder;
     rv = parent->GetChildNamed(childFolderName, getter_AddRefs(childFolder));
@@ -23,8 +28,13 @@ nsresult PopulateFolderHierarchy(nsIMsgFolder* parent,
     if (!childFolder) {
       rv = parent->AddSubfolder(childFolderName, getter_AddRefs(childFolder));
       if (NS_FAILED(rv) && rv != NS_MSG_FOLDER_EXISTS) {
-        return rv;
+        NS_WARNING(
+            nsPrintfCString("Unable to add child folder %s to parent %s.",
+                            childFolderName.Data(), parentName.Data())
+                .get());
+        continue;
       }
+
       NS_ENSURE_TRUE(childFolder, NS_ERROR_UNEXPECTED);

       // Check that we got a name from the folder database.  If not, set the
@@ -39,7 +49,12 @@ nsresult PopulateFolderHierarchy(nsIMsgFolder* parent,

     if (deep) {
       rv = PopulateFolderHierarchy(childFolder, messageStore, deep);
-      NS_ENSURE_SUCCESS(rv, rv);
+      if (NS_FAILED(rv)) {
+        NS_WARNING(
+            nsPrintfCString("Unable to populate child folder %s in parent %s.",
+                            childFolderName.Data(), parentName.Data())
+                .get());
+      }
     }
   }
   return NS_OK;
